-- Drop the old 1:1 salon application model; replaced by Business -> Shops hierarchy.
DROP TABLE `salons`;

CREATE TABLE `businesses` (`id` VARCHAR(191) NOT NULL, `owner_id` VARCHAR(191) NOT NULL, `brand_name` VARCHAR(160) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `businesses_owner_id_key` (`owner_id`), CONSTRAINT `businesses_owner_id_fkey` FOREIGN KEY (`owner_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `shops` (`id` VARCHAR(191) NOT NULL, `business_id` VARCHAR(191) NOT NULL, `name` VARCHAR(160) NOT NULL, `shop_type` VARCHAR(80) NULL, `contact_number` VARCHAR(24) NOT NULL, `email` VARCHAR(190) NULL, `address_line1` VARCHAR(255) NOT NULL, `address_line2` VARCHAR(255) NULL, `city` VARCHAR(120) NOT NULL, `state` VARCHAR(120) NOT NULL, `pincode` VARCHAR(16) NOT NULL, `latitude` DOUBLE NULL, `longitude` DOUBLE NULL, `description` TEXT NULL, `website` VARCHAR(255) NULL, `status` ENUM('DRAFT','LIVE','PAUSED') NOT NULL DEFAULT 'DRAFT', `booking_slug` VARCHAR(80) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `shops_booking_slug_key` (`booking_slug`), INDEX `shops_business_id_status_idx` (`business_id`,`status`), INDEX `shops_city_pincode_idx` (`city`,`pincode`), CONSTRAINT `shops_business_id_fkey` FOREIGN KEY (`business_id`) REFERENCES `businesses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `shop_hours` (`id` VARCHAR(191) NOT NULL, `shop_id` VARCHAR(191) NOT NULL, `day_of_week` INTEGER NOT NULL, `open_minutes` INTEGER NULL, `close_minutes` INTEGER NULL, `is_closed` BOOLEAN NOT NULL DEFAULT false, PRIMARY KEY (`id`), UNIQUE INDEX `shop_hours_shop_id_day_of_week_key` (`shop_id`,`day_of_week`), CONSTRAINT `shop_hours_shop_id_fkey` FOREIGN KEY (`shop_id`) REFERENCES `shops` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `shop_booking_settings` (`id` VARCHAR(191) NOT NULL, `shop_id` VARCHAR(191) NOT NULL, `advance_booking_days` INTEGER NOT NULL DEFAULT 30, `slot_interval_minutes` INTEGER NOT NULL DEFAULT 30, `cancellation_cutoff_hrs` INTEGER NOT NULL DEFAULT 24, `advance_notice_hours` INTEGER NOT NULL DEFAULT 2, `online_booking_enabled` BOOLEAN NOT NULL DEFAULT true, PRIMARY KEY (`id`), UNIQUE INDEX `shop_booking_settings_shop_id_key` (`shop_id`), CONSTRAINT `shop_booking_settings_shop_id_fkey` FOREIGN KEY (`shop_id`) REFERENCES `shops` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `shop_home_services` (`id` VARCHAR(191) NOT NULL, `shop_id` VARCHAR(191) NOT NULL, `enabled` BOOLEAN NOT NULL DEFAULT false, `coverage_radius_km` DOUBLE NULL, `serviceable_pincodes` TEXT NULL, `travel_buffer_minutes` INTEGER NOT NULL DEFAULT 30, PRIMARY KEY (`id`), UNIQUE INDEX `shop_home_services_shop_id_key` (`shop_id`), CONSTRAINT `shop_home_services_shop_id_fkey` FOREIGN KEY (`shop_id`) REFERENCES `shops` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `categories` (`id` VARCHAR(191) NOT NULL, `shop_id` VARCHAR(191) NOT NULL, `name` VARCHAR(120) NOT NULL, `sort_order` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`id`), INDEX `categories_shop_id_sort_order_idx` (`shop_id`,`sort_order`), CONSTRAINT `categories_shop_id_fkey` FOREIGN KEY (`shop_id`) REFERENCES `shops` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `subcategories` (`id` VARCHAR(191) NOT NULL, `category_id` VARCHAR(191) NOT NULL, `name` VARCHAR(120) NOT NULL, `sort_order` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`id`), INDEX `subcategories_category_id_sort_order_idx` (`category_id`,`sort_order`), CONSTRAINT `subcategories_category_id_fkey` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `services` (`id` VARCHAR(191) NOT NULL, `subcategory_id` VARCHAR(191) NOT NULL, `name` VARCHAR(160) NOT NULL, `description` TEXT NULL, `duration_minutes` INTEGER NOT NULL, `price` DECIMAL(10,2) NOT NULL, `compare_at_price` DECIMAL(10,2) NULL, `image_url` VARCHAR(500) NULL, `mode` ENUM('SALON','HOME','BOTH') NOT NULL DEFAULT 'BOTH', `online_booking_enabled` BOOLEAN NOT NULL DEFAULT true, `is_active` BOOLEAN NOT NULL DEFAULT true, `sort_order` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`id`), INDEX `services_subcategory_id_sort_order_idx` (`subcategory_id`,`sort_order`), CONSTRAINT `services_subcategory_id_fkey` FOREIGN KEY (`subcategory_id`) REFERENCES `subcategories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `service_addons` (`id` VARCHAR(191) NOT NULL, `service_id` VARCHAR(191) NOT NULL, `name` VARCHAR(120) NOT NULL, `price` DECIMAL(10,2) NOT NULL, `duration_minutes` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`id`), CONSTRAINT `service_addons_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `service_home_configs` (`id` VARCHAR(191) NOT NULL, `service_id` VARCHAR(191) NOT NULL, `extra_fee` DECIMAL(10,2) NULL, `free_radius_km` DOUBLE NULL, `serviceable_pincodes` TEXT NULL, `travel_buffer_minutes` INTEGER NOT NULL DEFAULT 30, `min_order_value` DECIMAL(10,2) NULL, `advance_hours` INTEGER NOT NULL DEFAULT 24, PRIMARY KEY (`id`), UNIQUE INDEX `service_home_configs_service_id_key` (`service_id`), CONSTRAINT `service_home_configs_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `staff_members` (`id` VARCHAR(191) NOT NULL, `business_id` VARCHAR(191) NOT NULL, `user_id` VARCHAR(191) NULL, `full_name` VARCHAR(120) NOT NULL, `mobile_number` VARCHAR(24) NOT NULL, `email` VARCHAR(190) NULL, `is_bookable` BOOLEAN NOT NULL DEFAULT true, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `staff_members_user_id_key` (`user_id`), UNIQUE INDEX `staff_members_business_id_mobile_number_key` (`business_id`,`mobile_number`), CONSTRAINT `staff_members_business_id_fkey` FOREIGN KEY (`business_id`) REFERENCES `businesses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `staff_members_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `shop_staff_assignments` (`id` VARCHAR(191) NOT NULL, `shop_id` VARCHAR(191) NOT NULL, `staff_id` VARCHAR(191) NOT NULL, `role` ENUM('OWNER','MANAGER','SUB_ADMIN','STAFF') NOT NULL DEFAULT 'STAFF', `can_take_bookings` BOOLEAN NOT NULL DEFAULT true, `permissions` TEXT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `shop_staff_assignments_shop_id_staff_id_key` (`shop_id`,`staff_id`), CONSTRAINT `shop_staff_assignments_shop_id_fkey` FOREIGN KEY (`shop_id`) REFERENCES `shops` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `shop_staff_assignments_staff_id_fkey` FOREIGN KEY (`staff_id`) REFERENCES `staff_members` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `shop_staff_hours` (`id` VARCHAR(191) NOT NULL, `assignment_id` VARCHAR(191) NOT NULL, `day_of_week` INTEGER NOT NULL, `start_minute` INTEGER NULL, `end_minute` INTEGER NULL, `is_off` BOOLEAN NOT NULL DEFAULT false, PRIMARY KEY (`id`), UNIQUE INDEX `shop_staff_hours_assignment_id_day_of_week_key` (`assignment_id`,`day_of_week`), CONSTRAINT `shop_staff_hours_assignment_id_fkey` FOREIGN KEY (`assignment_id`) REFERENCES `shop_staff_assignments` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `service_staff_assignments` (`id` VARCHAR(191) NOT NULL, `service_id` VARCHAR(191) NOT NULL, `staff_id` VARCHAR(191) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `service_staff_assignments_service_id_staff_id_key` (`service_id`,`staff_id`), CONSTRAINT `service_staff_assignments_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `service_staff_assignments_staff_id_fkey` FOREIGN KEY (`staff_id`) REFERENCES `staff_members` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `offers` (`id` VARCHAR(191) NOT NULL, `shop_id` VARCHAR(191) NOT NULL, `name` VARCHAR(160) NOT NULL, `description` TEXT NULL, `discount_type` ENUM('FLAT','PERCENTAGE','COMBO_PRICE') NOT NULL, `discount_value` DECIMAL(10,2) NULL, `fixed_price` DECIMAL(10,2) NULL, `start_at` DATETIME(3) NOT NULL, `end_at` DATETIME(3) NULL, `is_active` BOOLEAN NOT NULL DEFAULT true, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), INDEX `offers_shop_id_is_active_idx` (`shop_id`,`is_active`), CONSTRAINT `offers_shop_id_fkey` FOREIGN KEY (`shop_id`) REFERENCES `shops` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `offer_services` (`offer_id` VARCHAR(191) NOT NULL, `service_id` VARCHAR(191) NOT NULL, PRIMARY KEY (`offer_id`,`service_id`), CONSTRAINT `offer_services_offer_id_fkey` FOREIGN KEY (`offer_id`) REFERENCES `offers` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `offer_services_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `packages` (`id` VARCHAR(191) NOT NULL, `shop_id` VARCHAR(191) NOT NULL, `name` VARCHAR(160) NOT NULL, `description` TEXT NULL, `price` DECIMAL(10,2) NOT NULL, `validity_days` INTEGER NULL, `is_active` BOOLEAN NOT NULL DEFAULT true, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `packages_shop_id_fkey` FOREIGN KEY (`shop_id`) REFERENCES `shops` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `package_items` (`id` VARCHAR(191) NOT NULL, `package_id` VARCHAR(191) NOT NULL, `service_id` VARCHAR(191) NOT NULL, `quantity` INTEGER NOT NULL DEFAULT 1, PRIMARY KEY (`id`), UNIQUE INDEX `package_items_package_id_service_id_key` (`package_id`,`service_id`), CONSTRAINT `package_items_package_id_fkey` FOREIGN KEY (`package_id`) REFERENCES `packages` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `package_items_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `combos` (`id` VARCHAR(191) NOT NULL, `shop_id` VARCHAR(191) NOT NULL, `name` VARCHAR(160) NOT NULL, `description` TEXT NULL, `fixed_price` DECIMAL(10,2) NOT NULL, `is_active` BOOLEAN NOT NULL DEFAULT true, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `combos_shop_id_fkey` FOREIGN KEY (`shop_id`) REFERENCES `shops` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `combo_items` (`id` VARCHAR(191) NOT NULL, `combo_id` VARCHAR(191) NOT NULL, `service_id` VARCHAR(191) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `combo_items_combo_id_service_id_key` (`combo_id`,`service_id`), CONSTRAINT `combo_items_combo_id_fkey` FOREIGN KEY (`combo_id`) REFERENCES `combos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `combo_items_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
